      { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const result = invoiceTotals(invoice);

  // subtotal: 85000, discount: 8500, amount: 76500, vat: 16065, voucher: 5000
  // total: 85000 - 8500 + 16065 - 5000 = 87565
  assert.equal(result.subtotal, 85000);
  assert.equal(result.discount, 8500);
  assert.equal(result.vat, 16065);
  assert.equal(result.voucher, 5000);
  assert.equal(result.total, 87565);
});

test('invoiceTotals clamps total to 0', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, vatRate: 0 },
    ],
    voucher: { code: 'TEST', amount: 200 },
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.total, 0);
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
      { qty: 1000, unitPrice: 37, vatRate: 9 },
      { qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);

  // Line 1: subtotal 85000, vat 17850
  // Line 2: subtotal 37000, vat 3330
  // Line 3: subtotal 60000, vat 0
  // Total: subtotal 182000, vat 21180
  assert.equal(result.subtotal, 182000);
  assert.equal(result.vat, 21180);
  assert.equal(result.total, 203180);
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const invoice = createTestInvoice('C-001', '2026-09-01', [
    { sku: 'DES-HOUR', qty: 10 },
  ]);

  const result = invoiceTotals(invoice);

  // DES-HOUR: unitPrice 8500, vatRate 21, qty 10
  // C-001 is gold tier, so 5% discount
  // subtotal: 85000, discount: 4250, amount: 80750
  // vat: 80750 * 21 / 100 = 16957.5 ≈ 16958
  // total: 80750 + 16958 = 97708
  assert.equal(result.subtotal, 85000);
  assert.equal(result.discount, 4250);
  assert.equal(result.vat, 16958);
  assert.equal(result.voucher, 0);
  assert.equal(result.total, 97708);
});

test('invoiceTotals calculates all fields correctly together', () => {
  const invoice = createTestInvoice('C-002', '2026-09-01', [
    { sku: 'DES-HOUR', qty: 5 },
    { sku: 'STICKER', qty: 100 },
  ]);

  const result = invoiceTotals(invoice);

  // All amounts should be positive
  assert.ok(result.subtotal > 0);
  assert.ok(result.vat >= 0);
  assert.ok(result.total > 0);

  // Total should be: subtotal - discount + vat - voucher
  const calculated = result.subtotal - result.discount + result.vat - result.voucher;
  assert.equal(result.total, Math.max(0, calculated));
});

test('invoiceTotals handles empty lines gracefully', () => {
  // This shouldn't happen in practice, but test defensive behavior
  const invoice = {
    lines: [],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 0);
  assert.equal(result.discount, 0);
  assert.equal(result.vat, 0);
  assert.equal(result.voucher, 0);
  assert.equal(result.total, 0);
});

test('lineTotal, lineDiscount, lineVat work together', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 5, vatRate: 21 };

  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const vat = lineVat(line);

  // With qty=10, bulk discount applies (2.5% after initial discount)
  // Initial discount: 85000 * 5 / 100 = 4250
  // Amount after initial: 80750
  // Bulk discount: 80750 * 2.5 / 100 = 2019 (rounded)
  // Total discount: 4250 + 2019 = 6269
  assert.equal(discount, 6269);

  // VAT on amount after both discounts: (85000 - 6269) * 21 / 100
  assert.equal(vat, 16540);
});

test('invoiceTotals field relationships', () => {
  const invoice = createTestInvoice('C-001', '2026-09-01', [
    { sku: 'DES-HOUR', qty: 10 },
  ]);

  const result = invoiceTotals(invoice);

  // Verify: total = subtotal - discount + vat - voucher
  const expectedTotal = result.subtotal - result.discount + result.vat - result.voucher;
  assert.equal(result.total, Math.max(0, expectedTotal));
});

test('lineDiscount with bulk discount (qty >= 10)', () => {
  const line = { qty: 10, unitPrice: 8500, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 85000, no initial discount, bulk discount: 85000 * 2.5 / 100 = 2125
  assert.equal(result, 2125);
});

test('lineDiscount no bulk discount (qty < 10)', () => {
  const line = { qty: 9, unitPrice: 8500, vatRate: 21 };
  const result = lineDiscount(line);

  // No bulk discount applied
  assert.equal(result, 0);
});

test('lineDiscount with initial discount and bulk discount', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 85000
  // First discount: 85000 * 10 / 100 = 8500
  // Amount after first: 76500
  // Bulk discount: 76500 * 2.5 / 100 = 1912.5, banker's rounding → 1912
  // Total: 8500 + 1912 = 10412
  assert.equal(result, 10412);
});

test('lineDiscount with tier discount and bulk discount', () => {
  // C-001 has gold tier (5% discount)
  const invoice = createTestInvoice('C-001', '2026-09-01', [
    { sku: 'DES-HOUR', qty: 10 },
  ]);

  const line = invoice.lines[0];
  const discount = lineDiscount(line);

  // lineTotal: 85000
  // First discount (tier): 85000 * 5 / 100 = 4250
  // Amount after first: 80750
  // Bulk discount: 80750 * 2.5 / 100 = 2018.75 ≈ 2019 (rounded)
  // Total: 4250 + 2019 = 6269
  assert.equal(discount, 6269);
});

test('lineDiscount bulk discount with exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 10000, bulk discount: 10000 * 2.5 / 100 = 250
  assert.equal(result, 250);
});

test('lineDiscount no bulk discount with 9 units', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  const result = lineDiscount(line);

  // No discount
  assert.equal(result, 0);
});

test('lineDiscount bulk discount stacks with line discount', () => {
  const line = { qty: 20, unitPrice: 1000, discountPercent: 5, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 20000
  // First discount: 20000 * 5 / 100 = 1000
  // Amount after first: 19000
  // Bulk discount: 19000 * 2.5 / 100 = 475
  // Total: 1000 + 475 = 1475
  assert.equal(result, 1475);
});

test('lineVat applies to amount after both discounts', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 };
  const result = lineVat(line);

  // lineTotal: 85000
  // First discount: 8500, amount: 76500
  // Bulk discount: 76500 * 2.5 / 100 = 1912.5 ≈ 1913
  // Amount after both: 76500 - 1913 = 74587
  // VAT: 74587 * 21 / 100 = 15663.27 ≈ 15663
  assert.equal(result, 15663);
});

test('lineVat with bulk discount only', () => {
  const line = { qty: 10, unitPrice: 8500, vatRate: 21 };
  const result = lineVat(line);

  // lineTotal: 85000, bulk discount: 2125
  // Amount: 82875
  // VAT: 82875 * 21 / 100 = 17403.75 ≈ 17404
  assert.equal(result, 17404);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  // subtotal: 85000, discount: 2125 (bulk), amount: 82875, vat: 17404, total: 82875 + 17404 = 100279
  assert.equal(result.subtotal, 85000);
  assert.equal(result.discount, 2125);
  assert.equal(result.vat, 17404);
  assert.equal(result.total, 100279);
});

test('invoiceTotals aggregates bulk discounts from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
      { qty: 15, unitPrice: 50, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  // Line 1: subtotal 85000, bulk discount 2125
