  // lineTotal: 85000
  // First discount (line): 85000 * 5 / 100 = 4250
  // Amount after first: 80750
  // Bulk discount: 80750 * 2.5 / 100 = 2018.75 ≈ 2019
  // Total: 4250 + 2019 = 6269
  assert.equal(discount, 6269);
});

test('bulk discount 10 units with large unitPrice', () => {
  const line = { qty: 10, unitPrice: 120000, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 1200000, bulk discount: 1200000 * 2.5 / 100 = 30000
  assert.equal(result, 30000);
});

test('bulk discount calculation with rounding', () => {
  const line = { qty: 10, unitPrice: 333, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 3330, bulk discount: 3330 * 2.5 / 100 = 83.25 ≈ 83
  assert.equal(result, 83);
});

test('bulk discount with 0% initial discount still applies', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 10000
  // First discount: 0
  // Bulk discount: 10000 * 2.5 / 100 = 250
  // Total: 250
  assert.equal(result, 250);
});

