  const line = { qty: 100, unitPrice: 120000 };
  const result = lineTotal(line);
  assert.equal(result, 12000000);
});

test('lineDiscount no discount without bulk (qty < 10)', () => {
  const line = { qty: 5, unitPrice: 8500 };
  const result = lineDiscount(line);
  assert.equal(result, 0);
});

test('lineDiscount with bulk discount only (qty >= 10, no explicit discount)', () => {
  const line = { qty: 10, unitPrice: 8500 };
  const result = lineDiscount(line);
  // lineTotal: 85000, bulk discount: 85000 * 2.5 / 100 = 2125
  assert.equal(result, 2125);
});

test('lineDiscount with initial discount (qty < 10)', () => {
  const line = { qty: 5, unitPrice: 8500, discountPercent: 10 };
  const result = lineDiscount(line);
  // lineTotal: 42500, discount: 4250, no bulk discount (qty < 10)
  assert.equal(result, 4250);
});

test('lineDiscount with initial and bulk discount', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 10 };
  const result = lineDiscount(line);
  // Initial: 8500, bulk: 1912 (rounded), total: 10412
  assert.equal(result, 10412);
});

test('lineVat calculates without discount (qty < 10)', () => {
  const line = { qty: 5, unitPrice: 8500, vatRate: 21 };
