  // lineTotal: 42500, VAT: 42500 * 21 / 100 = 8925
  assert.equal(result, 8925);
});

test('lineVat applies to amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 8500, vatRate: 21 };
  const result = lineVat(line);
  // lineTotal: 85000, bulk discount: 2125, amount: 82875
  // VAT: 82875 * 21 / 100 = 17404
  assert.equal(result, 17404);
});

