  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 42500);
  assert.equal(result.discount, 0);
  assert.equal(result.vat, 8925);
});

test('invoiceTotals single line with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 85000);
  assert.equal(result.discount, 2125);
  assert.equal(result.vat, 17404);
  assert.equal(result.total, 100279);
});

test('invoiceTotals multiple lines with bulk discount on some', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  // Line 1: 10000, bulk discount: 250
  // Line 2: 5000, no bulk discount
  assert.equal(result.subtotal, 15000);
  assert.equal(result.discount, 250);
});

test('lineDiscount bulk discount with 0% explicit discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const result = lineDiscount(line);
  // Bulk discount: 10000 * 2.5 / 100 = 250
  assert.equal(result, 250);
});

test('invoiceTotals with tier and bulk discount', () => {
  const invoice = createTestInvoice('C-001', '2026-09-01', [
    { sku: 'DES-HOUR', qty: 10 },
  ]);

  const result = invoiceTotals(invoice);

  // Tier discount: 4250, bulk discount: 2019, total: 6269
  assert.equal(result.discount, 6269);
  assert.ok(result.total > 0);
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 500 },
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.voucher, 500);
  assert.ok(result.total < 5000 + 1050); // total after voucher
});

test('invoiceTotals with all discounts stacked', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 100 },
  };
  const result = invoiceTotals(invoice);

  // Line: 10000
  // Initial discount: 500, amount: 9500
  // Bulk discount: 237.5 ≈ 238, total discount: 738
  // Amount: 9262, VAT: 9262 * 21% = 1945, total: 9262 + 1945 - 100 = 11107
  assert.equal(result.subtotal, 10000);
  assert.ok(result.discount > 500);
  assert.ok(result.vat > 0);
  assert.equal(result.voucher, 100);
});

test('invoiceTotals clamped to 0', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, vatRate: 0 },
    ],
    voucher: { code: 'TEST', amount: 200 },
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.total, 0);
});

test('bulk discount with large qty', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 100000, bulk discount: 100000 * 2.5 / 100 = 2500
  assert.equal(result, 2500);
});

test('bulk discount exactly at threshold (qty = 10)', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 21 };
  const result = lineDiscount(line);

  // lineTotal: 1000, bulk discount: 1000 * 2.5 / 100 = 25
  assert.equal(result, 25);
});

test('no bulk discount just below threshold (qty = 9)', () => {
  const line = { qty: 9, unitPrice: 100, vatRate: 21 };
  const result = lineDiscount(line);

  assert.equal(result, 0);
});

