test('lineDiscount calculates discount amount', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 20 };
  const discount = lineDiscount(line);
  assert.equal(discount, 17000);
});

test('lineDiscount rounds to whole cents', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 100, vatRate: 21, discountPercent: 33.33 };
  const discount = lineDiscount(line);
  assert.equal(Number.isInteger(discount), true);
});

test('lineDiscount returns 0 for no discount', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineDiscount(line), 0);
});

test('invoiceTotals with discount', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16065);
  assert.equal(totals.total, 92565);
});

test('invoiceTotals with multiple lines and mixed discounts', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 18000);
  const afterDiscount = 132500 - 18000;
  const expectedVat = Math.round(afterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 132500 - 18000 + expectedVat);
});

test('invoiceTotals total is clamped to 0', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', name: 'Sticker sheet', qty: 1, unitPrice: 50, vatRate: 21, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.discount, 50);
  assert.equal(totals.total, 0);
});

test('addLine with discountPercent', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
    ],
  };
