  const r100 = createInvoice({ customerId: 'C-003', issueDate: '2026-10-07', lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 100 }] });
  assert.equal(r100.ok, true);
  const r50decimal = createInvoice({ customerId: 'C-003', issueDate: '2026-10-07', lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 12.5 }] });
