test('invoiceTotals includes tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 85000);
  // Tier: 4250, bulk: 2019, total: 6269
  assert.equal(totals.discount, 6269);
  // VAT on 78731: 16534
  assert.equal(totals.vat, 16534);
  assert.equal(totals.total, 95265);
});

test('lineVat calculates VAT on line amount after discount', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 };
  const vat = lineVat(line);
  // Initial: 8500, bulk: 1912, total discount: 10412
  // Amount after: 74588, VAT: 15663
  assert.equal(vat, 15663);
});

test('lineVat with no discount', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 };
  const vat = lineVat(line);
  // Bulk discount only (no explicit discount): 2125
  // Amount after: 82875, VAT: 17404
  assert.equal(vat, 17404);
});

test('lineVat with different VAT rates', () => {
  const line21 = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 100, unitPrice: 1000, vatRate: 21 };
  // Bulk discount: 2500, amount after: 97500, VAT: 20475
  assert.equal(lineVat(line21), 20475);

  const line9 = { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 1000, vatRate: 9 };
  // Bulk discount: 2500, amount after: 97500, VAT: 8775
  assert.equal(lineVat(line9), 8775);

  const line0 = { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 100, unitPrice: 1000, vatRate: 0 };
  assert.equal(lineVat(line0), 0);
});

test('lineVat rounds to whole cents', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 100, vatRate: 33.33 };
  const vat = lineVat(line);
  assert.equal(Number.isInteger(vat), true);
});

test('invoiceTotals with VAT', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.total, 85000 + 17850);
  assert.equal(totals.total, 102850);
});

test('invoiceTotals with multiple lines and mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 85000;
  const line1Vat = 17850;
  const line2Total = 3700;
  const line2Vat = 333;
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, line1Vat + line2Vat);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals VAT 0 for exempt items', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

