test('lineVat with different VAT rates', () => {
  const line21 = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 100, unitPrice: 1000, vatRate: 21 };
  // Bulk discount: 2500, amount after: 97500, VAT: 20475
  assert.equal(lineVat(line21), 20475);

  const line9 = { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 1000, vatRate: 9 };
  // Bulk discount: 2500, amount after: 97500, VAT: 8775
  assert.equal(lineVat(line9), 8775);

  const line0 = { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 100, unitPrice: 1000, vatRate: 0 };
  assert.equal(lineVat(line0), 0);
