});

test('invoiceTotals with VAT', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.total, 85000 + 17850);
  assert.equal(totals.total, 102850);
});

test('invoiceTotals with multiple lines and mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 85000;
  const line1Vat = 17850;
  const line2Total = 3700;
  const line2Vat = 333;
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, line1Vat + line2Vat);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals VAT 0 for exempt items', () => {
