import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVat, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r1 = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: '  C-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);
  assert.equal(r1.value.customerId, 'C-003');
  assert.equal(r2.value.customerId, 'C-003');
});

test('createInvoice uses NET30 as default terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    terms: 'NET30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    terms: 'EOM',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice rejects invalid terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    terms: 'INVALID',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice calculates EOM for different months', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    terms: 'EOM',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r1.value.dueDate, '2026-01-31');

  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-15',
    terms: 'EOM',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r2.value.dueDate, '2026-02-28');

  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    terms: 'EOM',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r3.value.dueDate, '2024-02-29');
});

test('applyVoucher adds a voucher to a draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const r = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 5000);
});

test('applyVoucher rejects non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  assert.deepEqual(applyVoucher(issuedInvoice, { code: 'SUMMER2026', amount: 5000 }), { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects duplicate vouchers', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const r1 = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(r1.ok, true);

  const r2 = applyVoucher(r1.value, { code: 'ANOTHER', amount: 2000 });
  assert.deepEqual(r2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher rejects invalid amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: 0 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: -1000 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: 100.5 }), { ok: false, error: 'AMOUNT_INVALID' });
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const withVoucher = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 }).value;

  const totals = invoiceTotals(withVoucher);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 5000);
});

test('invoiceTotals voucher is 0 without a voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const originalVoucher = invoice.voucher;
  applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });

  assert.equal(invoice.voucher, originalVoucher);
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
